import{_ as s,o as t,c as i,a8 as o}from"./chunks/framework.BppdKxCY.js";const k=JSON.parse('{"title":"EP.07 XSS 与 CSRF 攻防","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.07-xss-csrf-defense.md","filePath":"comics/EP.07-xss-csrf-defense.md","lastUpdated":1792817913000}'),a={name:"comics/EP.07-xss-csrf-defense.md"};function l(n,e,r,c,h,d){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="ep-07-xss-与-csrf-攻防" tabindex="-1">EP.07 XSS 与 CSRF 攻防 <a class="header-anchor" href="#ep-07-xss-与-csrf-攻防" aria-label="Permalink to &quot;EP.07 XSS 与 CSRF 攻防&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../07-security">07-security.md</a>（7.1 XSS 跨站脚本攻击 / 7.2 CSRF 跨站请求伪造）· 示例：<code>examples/07-01-xss-defense.ts</code>、<code>examples/07-02-csrf-defense.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君的评论区被人塞了脚本，其他用户一打开页面 Cookie 就被偷——存储型 XSS。</li><li><strong>第 2 格</strong>：码叔揭秘防御三件套：输出转义（textContent）、CSP 白名单、HttpOnly Cookie。</li><li><strong>第 3 格</strong>：像素酱实证 CSRF——钓鱼站偷偷向银行发请求，浏览器自动带上 Cookie 完成转账。</li><li><strong>第 4 格</strong>：码叔结案——黑名单过滤不可靠，防御靠&quot;转义、白名单、最小权限&quot;的纵深体系。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-xss-的本质" tabindex="-1">第 1 格 · XSS 的本质 <a class="header-anchor" href="#第-1-格-·-xss-的本质" aria-label="Permalink to &quot;第 1 格 · XSS 的本质&quot;">​</a></h3><ul><li><strong>数据被当成代码执行</strong>：用户输入未转义就插入 HTML；</li><li>三种类型：<strong>存储型</strong>（入库持久化，危害最大）、<strong>反射型</strong>（URL 参数携带，点击触发）、<strong>DOM 型</strong>（纯前端拼接 innerHTML）；</li><li>危害：偷 Cookie、伪造请求、键盘记录、页面篡改。</li></ul><h3 id="第-2-格-·-xss-防御三件套" tabindex="-1">第 2 格 · XSS 防御三件套 <a class="header-anchor" href="#第-2-格-·-xss-防御三件套" aria-label="Permalink to &quot;第 2 格 · XSS 防御三件套&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">el.textContent </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> userInput;          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ① 不解析 HTML，文本化输出</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Content-Security-Policy: &#39;self&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // ② CSP：限制脚本来源</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Set-Cookie: token=xx; HttpOnly</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ③ JS 读不到 Cookie</span></span></code></pre></div><ul><li><strong>转义</strong>是根本：React/Vue 默认转义插值，只有 <code>dangerouslySetInnerHTML</code>/<code>v-html</code> 是逃生舱；</li><li><strong>CSP</strong> 限制页面能加载哪些脚本，即使注入成功也难以执行外链脚本；</li><li><strong>HttpOnly</strong> 让 <code>document.cookie</code> 读不到会话 Cookie，偷了也没用。</li></ul><h3 id="第-3-格-·-csrf-的原理" tabindex="-1">第 3 格 · CSRF 的原理 <a class="header-anchor" href="#第-3-格-·-csrf-的原理" aria-label="Permalink to &quot;第 3 格 · CSRF 的原理&quot;">​</a></h3><ul><li>用户在 A 站登录后，浏览器保存了 Cookie；</li><li>访问恶意站 B 时，B 偷偷向 A 发请求，<strong>浏览器自动携带 A 站 Cookie</strong>；</li><li>服务器无法区分&quot;用户本人发的&quot;和&quot;钓鱼站借用户身份发的&quot;。</li></ul><h3 id="第-4-格-·-csrf-防御" tabindex="-1">第 4 格 · CSRF 防御 <a class="header-anchor" href="#第-4-格-·-csrf-防御" aria-label="Permalink to &quot;第 4 格 · CSRF 防御&quot;">​</a></h3><ul><li><strong>CSRF Token</strong>：表单/请求头带服务端下发的随机 Token，钓鱼站拿不到；</li><li><strong>SameSite Cookie</strong>：<code>Lax</code>/<code>Strict</code> 阻止跨站请求自动携带 Cookie；</li><li><strong>校验 Origin/Referer</strong>：服务端核对请求来源，非白名单直接拒绝。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../07-security#_7-7-本章避坑清单">《7.7 本章避坑清单》</a></p></blockquote><ol><li>用 innerHTML + 黑名单过滤&quot;富文本&quot;：变体绕过层出不穷，要白名单（DOMPurify）；</li><li>Cookie 没设 HttpOnly + Secure：XSS 一旦得手会话直接沦陷；</li><li>只依赖 Referer 防 CSRF：隐私设置会剥离 Referer，Token + SameSite 才是主力。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>存储型 XSS 和反射型 XSS 的区别？——<strong>存储型入库持久化，所有访问者中招；反射型藏在 URL 参数里，需诱导点击</strong>。</li><li>CSRF 能不能靠&quot;检查请求头 X-Requested-With&quot;完全防住？——<strong>不能单独防，需 CSRF Token + SameSite + Origin 校验组合纵深防御</strong>。</li><li>HttpOnly 防的是什么？防不了什么？——<strong>防 JS 通过 document.cookie 读会话 Cookie；不能阻止 XSS 注入本身</strong>。</li></ol>`,19)])])}const S=s(a,[["render",l]]);export{k as __pageData,S as default};
